const campusVideo=document.querySelector('#campus-video');const videoToggle=document.querySelector('#video-toggle');const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');function videoLabel(){const paused=campusVideo.paused;videoToggle.innerHTML=paused?'▶ <span>Play film</span>':'Ⅱ <span>Pause film</span>';videoToggle.setAttribute('aria-label',paused?'Play campus background video':'Pause campus background video')}videoToggle.onclick=()=>{if(campusVideo.paused)campusVideo.play().catch(videoLabel);else campusVideo.pause()};campusVideo.addEventListener('play',videoLabel);campusVideo.addEventListener('pause',videoLabel);if(reducedMotion.matches)campusVideo.pause();else campusVideo.play().catch(videoLabel);reducedMotion.addEventListener('change',e=>{if(e.matches)campusVideo.pause()});document.querySelector('#watch-film').onclick=()=>{campusVideo.pause();show('A glimpse of life at SVS','<iframe src="https://drive.google.com/file/d/1c9aA98tMD-yLNcmo3dJ79rZTDowEAszM/preview" title="SVS college campus film" allow="autoplay; fullscreen" allowfullscreen></iframe><p>College film supplied for this presentation. <a href="https://drive.google.com/file/d/1c9aA98tMD-yLNcmo3dJ79rZTDowEAszM/view" target="_blank" rel="noopener">Open film in Google Drive ↗</a></p>','THE SVS CAMPUS FILM');dialog.classList.add('film-dialog')};dialog.addEventListener('close',()=>{if(dialog.classList.contains('film-dialog')){dialog.classList.remove('film-dialog');document.querySelector('#dialog-content').innerHTML=''}});
